# todo - a persistent task list
let dataDir = home() + "/data"
mkdir -p dataDir
let store = dataDir + "/todo.txt"
let a = args()
let action = "list"
if (len(a) > 0) {
  action = a[0]
}

if (action == "add") {
  if (len(a) < 2) {
    echo "usage: todo add <text>"
  } else {
    echo a[1] >> store
    echo "added: ${a[1]}"
  }
} else {
  if (action == "done") {
    if (len(a) < 2) {
      echo "usage: todo done <number>"
    } else {
      let items = []
      if (exists(store)) {
        items = split(read(store), "\n")
      }
      let wanted = math(a[1])
      let kept = []
      for i in range(0, len(items)) {
        if (i != wanted - 1) {
          kept = kept + [items[i]]
        }
      }
      echo "" > store
      for item in kept {
        echo item >> store
      }
      echo "removed item ${wanted}"
    }
  } else {
    if (action == "clear") {
      echo "" > store
      echo "todo list cleared"
    } else {
      let items = []
      if (exists(store)) {
        items = split(read(store), "\n")
      }
      if (len(items) == 0) {
        echo "Nothing to do. Enjoy your day!"
      } else {
        for item in items {
          echo item
        }
      }
    }
  }
}

# notes - simple persistent notes
let dataDir = home() + "/data"
mkdir -p dataDir
let store = dataDir + "/notes.txt"
let a = args()

if (len(a) > 0) {
  if (a[0] == "add") {
    if (len(a) < 2) {
      echo "usage: notes add <text>"
    } else {
      echo a[1] >> store
      echo "saved note"
    }
  } else {
    if (a[0] == "find") {
      if (len(a) < 2) {
        echo "usage: notes find <term>"
      } else {
        if (exists(store)) {
          let notes = split(read(store), "\n")
          for note in notes {
            if (contains(note, a[1])) {
              echo note
            }
          }
        } else {
          echo "No notes yet."
        }
      }
    } else {
      echo "usage: notes add <text> | notes list | notes find <term>"
    }
  }
} else {
  if (exists(store)) {
    cat store
  } else {
    echo "No notes yet."
  }
}

# wordcount - count lines, words and characters
let a = args()
let input = ""
if (len(a) > 0) {
  input = read(a[0])
} else {
  input = read()
}
let words = split(input)
let lines = split(input, "\n")
echo "lines:      ${len(lines)}"
echo "words:      ${len(words)}"
echo "characters: ${len(input)}"

# jsonfmt - pretty-print JSON
let a = args()
let source = ""
if (len(a) > 0) {
  source = a[0]
} else {
  source = read()
}
if (source == "") {
  echo "usage: jsonfmt '<json>'"
} else {
  echo json(json("--parse", source))
}

# treeview - a compact directory tree
fn tree(dir, prefix, depth) {
  if (depth > 4) {
    return
  }
  for entry in ls(dir) {
    let parts = split(entry, "/")
    let name = parts[len(parts) - 1]
    let child = dir + "/" + name
    echo (prefix + "|-- " + name)
    if (isdir(child)) {
      tree(child, prefix + "  ", depth + 1)
    }
  }
}
let a = args()
let root = "."
if (len(a) > 0) {
  root = a[0]
}
echo root
tree(root, "", 0)

# gitinfo - current repository summary
echo "branch:   ${$(git rev-parse --abbrev-ref HEAD)}"
echo "commit:   ${$(git rev-parse --short HEAD)}"
let status = $(git status --short)
if (status == "") {
  echo "status:   clean"
} else {
  echo "status:"
  echo status
}

# backup - timestamped local copy
let a = args()
if (len(a) < 1) {
  echo "usage: backup <path>"
} else {
  let source = a[0]
  let stamp = $(date +%Y%m%d-%H%M%S)
  let targetDir = home() + "/backups"
  mkdir -p targetDir
  let target = targetDir + "/" + stamp
  cp -R source target
  echo "backed up ${source} to ${target}"
}

# countdown - a tiny timer
let a = args()
if (len(a) == 0) {
  echo "usage: countdown <seconds>"
} else {
  let n = math(a[0])
  while (n > 0) {
    echo n
    sleep 1
    n = n - 1
  }
  echo "Go!"
}

# netcheck - simple host reachability check
let a = args()
let host = "example.com"
if (len(a) > 0) {
  host = a[0]
}
echo "checking ${host}"
let result = $(ping -c 1 -W 2 host)
if (result == "") {
  echo "no response from ${host}"
} else {
  echo "${host} responded"
}

# dice - roll dice locally
let a = args()
let sides = 6
let count = 1
if (len(a) > 0) {
  sides = math(a[0])
}
if (len(a) > 1) {
  count = math(a[1])
}
for i in range(0, count) {
  let roll = random(sides) + 1
  echo roll
}
